char pairs(char a) {
  if (a == '}') return '{';
  if (a == ']') return '[';
  if (a == ')') return '(';
  return 0;
}

bool isValid(char *s) {
  int n = strlen(s);
  if (n % 2 == 1) {
    return false;
  }
  int stk[n + 1], top = 0;
  for (int i = 0; i < n; i++) {
    char ch = pairs(s[i]);
    if (ch) {
      if (top == 0 || stk[top - 1] != ch) {
        return false;
      }
      top--;
    } else {
      stk[top++] = s[i];
    }
  }
  return top == 0;
}

class Solution {
public:
  bool isValid(string s) {
    int n = s.size();
    if (n % 2 == 1) {
      return false;
    }

    unordered_map<char, char> pairs = {
        {')', '('},
        {']', '['},
        {'}', '{'}};
    stack<char> stk;
    for (char ch : s) {
      if (pairs.count(ch)) {
        if (stk.empty() || stk.top() != pairs[ch]) {
          return false;
        }
        stk.pop();
      } else {
        stk.push(ch);
      }
    }
    return stk.empty();
  }
};

